import React, { useEffect, useState, useRef } from 'react';

/**
 * Moodle globals.
 */
declare const M: any;

/**
 * Props for the Map component.
 */
interface MapProps {
    courseid: number;
    editing: boolean;
}

/**
 * Node data from the backend.
 */
interface MapNode {
    id: number;
    sectionid: number;
    cmid: number;
    x: number;
    y: number;
    metadata: string;
}

/**
 * QuestFlow Map Component.
 *
 * @param {MapProps} props The component props.
 * @returns {JSX.Element} The rendered map.
 */
const Map = ({ courseid, editing }: MapProps) => {
    const [nodes, setNodes] = useState<MapNode[]>([]);
    const [loading, setLoading] = useState(true);
    const [draggingNodeId, setDraggingNodeId] = useState<number | null>(null);
    const svgRef = useRef<SVGSVGElement>(null);

    useEffect(() => {
        /**
         * Fetch map data from Moodle Web Service.
         */
        const fetchMapData = async () => {
            try {
                const response = await fetch(`${M.cfg.wwwroot}/lib/ajax/service.php?sesskey=${M.cfg.sesskey}`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify([{
                        index: 0,
                        methodname: 'format_questflow_get_map_data',
                        args: { courseid }
                    }])
                });
                const data = await response.json();
                if (data[0] && !data[0].error) {
                    setNodes(data[0].data.nodes);
                }
            } catch (error) {
                console.error('QuestFlow: Failed to fetch map data', error);
            } finally {
                setLoading(false);
            }
        };

        fetchMapData();
    }, [courseid]);

    /**
     * Handle mouse move for dragging nodes.
     */
    const handleMouseMove = (e: React.MouseEvent) => {
        if (!editing || draggingNodeId === null || !svgRef.current) return;

        const CTM = svgRef.current.getScreenCTM();
        if (!CTM) return;

        const x = Math.round((e.clientX - CTM.e) / CTM.a);
        const y = Math.round((e.clientY - CTM.f) / CTM.d);

        setNodes(prevNodes => prevNodes.map(node => 
            node.id === draggingNodeId ? { ...node, x, y } : node
        ));
    };

    /**
     * Handle mouse up to stop dragging and save position.
     */
    const handleMouseUp = async () => {
        if (!editing || draggingNodeId === null) return;

        const node = nodes.find(n => n.id === draggingNodeId);
        setDraggingNodeId(null);

        if (node) {
            try {
                await fetch(`${M.cfg.wwwroot}/lib/ajax/service.php?sesskey=${M.cfg.sesskey}`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify([{
                        index: 0,
                        methodname: 'format_questflow_save_node_position',
                        args: {
                            courseid,
                            nodeid: node.id,
                            sectionid: node.sectionid,
                            cmid: node.cmid,
                            x: node.x,
                            y: node.y
                        }
                    }])
                });
            } catch (error) {
                console.error('QuestFlow: Failed to save node position', error);
            }
        }
    };

    if (loading) {
        return (
            <div className="format-questflow-map-container" style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '600px', backgroundColor: '#0f172a' }}>
                <div className="spinner-border text-primary" role="status"></div>
            </div>
        );
    }

    return (
        <div 
            className="format-questflow-map-container" 
            style={{ position: 'relative', width: '100%', height: '600px', backgroundColor: '#0f172a', overflow: 'hidden', borderRadius: '12px' }}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
        >
            <svg ref={svgRef} width="100%" height="100%" style={{ display: 'block' }}>
                <defs>
                    <linearGradient id="path_grad" x1="0%" y1="0%" x2="100%" y2="0%">
                        <stop offset="0%" style={{ stopColor: '#3b82f6', stopOpacity: 1 }} />
                        <stop offset="100%" style={{ stopColor: '#60a5fa', stopOpacity: 1 }} />
                    </linearGradient>
                    <filter id="node_glow">
                        <feGaussianBlur stdDeviation="3" result="blur" />
                        <feComposite in="SourceGraphic" in2="blur" operator="over" />
                    </filter>
                </defs>

                {/* Draw paths between nodes */}
                {nodes.length > 1 && nodes.map((node, index) => {
                    if (index === 0) return null;
                    const prevNode = nodes[index - 1];
                    return (
                        <line 
                            key={`path-${index}`}
                            x1={prevNode.x} y1={prevNode.y} 
                            x2={node.x} y2={node.y} 
                            stroke="url(#path_grad)" 
                            strokeWidth="4" 
                            strokeDasharray="8 4" 
                            opacity="0.3" 
                        />
                    );
                })}
                
                {/* Render nodes from database */}
                {nodes.length > 0 ? nodes.map((node) => (
                    <g 
                        key={node.id} 
                        className="quest-node" 
                        style={{ cursor: editing ? 'grab' : 'pointer' }}
                        onMouseDown={() => editing && setDraggingNodeId(node.id)}
                    >
                        <circle cx={node.x} cy={node.y} r="15" fill="#f59e0b" filter="url(#node_glow)" />
                        <text x={node.x} y={node.y + 40} fill="white" fontSize="12" textAnchor="middle" fontFamily="sans-serif" pointerEvents="none">
                            {node.cmid ? `Activity ${node.cmid}` : `Chapter ${node.sectionid}`}
                        </text>
                    </g>
                )) : (
                    <text x="50%" y="50%" fill="white" textAnchor="middle" fontSize="18">
                        No quest nodes found. Add chapters to begin.
                    </text>
                )}
            </svg>

            {/* Overlay Info */}
            <div style={{ position: 'absolute', top: '20px', left: '20px', background: 'rgba(30, 41, 59, 0.8)', color: 'white', padding: '15px', borderRadius: '8px', border: '1px solid #334155', backdropFilter: 'blur(4px)', pointerEvents: 'none' }}>
                <h3 style={{ margin: 0, fontSize: '1.2rem' }}>QuestFlow Journey</h3>
                <p style={{ margin: '5px 0 0', opacity: 0.8, fontSize: '0.9rem' }}>
                    {nodes.length} Nodes | {editing ? 'Edit Mode' : 'View Mode'}
                </p>
            </div>
        </div>
    );
};

export default Map;
